impl Predict for FittedComPoissonHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for ComPoissonHmm {
    type Fitted = FittedComPoissonHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedComPoissonHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        if t_len == 0 {
            return ctx.finish(FittedComPoissonHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                lam: Vector::filled(k, 1.0),
                nu: Vector::filled(k, 1.0),
                loglik: f64::NAN,
            });
        }
        let mut lam = Vector::from_iter((0..k).map(|j| 1.0 + 2.0 * j as f64));
        let mut nu = Vector::filled(k, 1.0);
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedComPoissonHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                lam: lam.clone(),
                nu: nu.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wy = 0.0_f64;
                let mut wy2 = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y < 0.0 {
                        continue;
                    }
                    let w = fb.gamma[t][j];
                    wsum += w;
                    wy += w * y;
                    wy2 += w * y * y;
                }
                if wsum > 1e-12 {
                    let m = (wy / wsum).max(1e-4);
                    lam[j] = m.min(40.0);
                    let v = (wy2 / wsum - m * m).max(1e-4);
                    nu[j] = (m / v).clamp(0.2, 8.0);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedComPoissonHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            lam: lam.clone(),
            nu: nu.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedComPoissonHmm {
            labels,
            start,
            trans,
            lam,
            nu,
            loglik,
        })
    }
}

