impl FitUnsupervised for WrappedLevyHmm {
    type Fitted = FittedWrappedLevyHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedWrappedLevyHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let loc = -std::f64::consts::PI - 0.25;
        if t_len == 0 {
            return ctx.finish(FittedWrappedLevyHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                loc,
                scale: Vector::filled(k, 1.0),
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..k).map(|j| 0.6 + 0.5 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedWrappedLevyHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                loc,
                scale: scale.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut winv = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() {
                        continue;
                    }
                    let d = (wrap_pi(y) - loc).max(1e-8);
                    wsum += fb.gamma[t][j];
                    winv += fb.gamma[t][j] / d;
                }
                if wsum > 1e-12 && winv > 1e-12 {
                    scale[j] = (wsum / winv).max(COV_FLOOR);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedWrappedLevyHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            loc,
            scale: scale.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedWrappedLevyHmm {
            labels,
            start,
            trans,
            loc,
            scale,
            loglik,
        })
    }
}

