/// Shape \(\alpha>1\) is a hyperparameter, not identification `p`. Distinct
/// from [`GeometricHmm`] (point \(p\)) and [`BetaBinomialHmm`] (fixed \(n\)).
#[derive(Clone, Debug)]
pub struct BetaGeometricHmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for BetaGeometricHmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl BetaGeometricHmm {
    /// `k`-state beta-geometric HMM.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedBetaGeometricHmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted beta-geometric HMM.
#[derive(Clone, Debug)]
pub struct FittedBetaGeometricHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Beta shapes \(\alpha_j>1\).
    pub alpha: Vector,
    /// Beta shapes \(\beta_j\).
    pub beta: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedBetaGeometricHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.alpha.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_beta_geometric(y, self.alpha[j], self.beta[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedBetaGeometricHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for BetaGeometricHmm {
    type Fitted = FittedBetaGeometricHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedBetaGeometricHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let alpha = Vector::from_iter((0..k).map(|j| 1.3 + 0.8 * j as f64));
        if t_len == 0 {
            return ctx.finish(FittedBetaGeometricHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                alpha,
                beta: Vector::filled(k, 1.0),
                loglik: f64::NAN,
            });
        }
        let mut beta = Vector::from_iter((0..k).map(|j| 0.8 + 0.4 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedBetaGeometricHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                alpha: alpha.clone(),
                beta: beta.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wy = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y < 1.0 - 1e-9 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    wy += fb.gamma[t][j] * y.round().max(1.0);
                }
                if wsum > 1e-12 {
                    let mean = (wy / wsum).max(1.01);
                    beta[j] = ((mean - 1.0) * (alpha[j] - 1.0)).clamp(0.05, 40.0);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedBetaGeometricHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            alpha: alpha.clone(),
            beta: beta.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedBetaGeometricHmm {
            labels,
            start,
            trans,
            alpha,
            beta,
            loglik,
        })
    }
}

fn log_akash(y: f64, theta: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 {
        return f64::NEG_INFINITY;
    }
    3.0 * theta.ln() - (theta * theta + 2.0).ln() + 2.0 * (1.0 + y).ln() - theta * y
}

fn log_inv_exponential(y: f64, lam: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || lam <= 0.0 {
        return f64::NEG_INFINITY;
    }
    lam.ln() - 2.0 * y.ln() - lam / y
}

fn log_mo_exponential(y: f64, lam: f64, alpha: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || lam <= 0.0 || alpha <= 0.0 || alpha >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let e = (-lam * y).exp();
    let den = 1.0 - alpha * e;
    if den <= 1e-12 {
        return f64::NEG_INFINITY;
    }
    lam.ln() + (1.0 - alpha).ln() - lam * y - 2.0 * den.ln()
}

fn log_muth(y: f64, alpha: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || alpha <= 0.0 || alpha > 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let z = y / scale;
    let az = alpha * z;
    if az > 20.0 {
        return f64::NEG_INFINITY;
    }
    let ea = az.exp();
    let haz = ea - (1.0 - alpha);
    if haz <= 1e-12 {
        return f64::NEG_INFINITY;
    }
    -scale.ln() + haz.ln() - (ea - 1.0) / alpha + (1.0 - alpha) * z
}

fn log_wrapped_gumbel(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let theta = wrap_pi(y);
    let mut terms = Vec::with_capacity(7);
    for k in -3..=3 {
        let t = theta + (k as f64) * std::f64::consts::TAU;
        let v = log_gumbel(t, loc, scale);
        if v.is_finite() {
            terms.push(v);
        }
    }
    if terms.is_empty() {
        f64::NEG_INFINITY
    } else {
        logsumexp(&terms)
    }
}

/// Akash lifetime HMM (Shanker; \((1+x)^2 e^{-\\theta x}\)).
///
/// Rate \(\theta\) is not identification `p`. Distinct from [`LindleyHmm`]
/// (\((1+x)\)) and [`XgammaHmm`] (\((1+\theta x/2)\)).
#[derive(Clone, Debug)]
pub struct AkashHmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for AkashHmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl AkashHmm {
    /// `k`-state Akash HMM.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(&mut self, x: &Matrix, session: &Session) -> Result<Qualified<FittedAkashHmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted Akash HMM.
#[derive(Clone, Debug)]
pub struct FittedAkashHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Rates \(\theta_j\).
    pub theta: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedAkashHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.theta.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_akash(y, self.theta[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

