impl FitUnsupervised for IshitaHmm {
    type Fitted = FittedIshitaHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedIshitaHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let mut n_skip = 0usize;
        for i in 0..t_len {
            if x.get(i, 0).is_finite() && x.get(i, 0) <= 0.0 {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!("IshitaHmm skipped {n_skip} non-positive observations"))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedIshitaHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                theta: Vector::filled(k, 0.8),
                loglik: f64::NAN,
            });
        }
        let mut theta = Vector::from_iter((0..k).map(|j| 0.4 + 0.3 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedIshitaHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                theta: theta.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wy = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    wy += fb.gamma[t][j] * y;
                }
                if wsum <= 1e-12 {
                    continue;
                }
                let m = (wy / wsum).max(1e-4);
                let mut th = theta[j];
                for _ in 0..6 {
                    let den = th * th * th + 2.0;
                    let g = 3.0 / th - 3.0 * th * th / den - m;
                    let gp = -3.0 / (th * th) - 3.0 * th * (4.0 - th * th * th) / (den * den);
                    if gp.abs() > 1e-12 {
                        th = (th - g / gp).clamp(1e-3, 40.0);
                    }
                }
                theta[j] = th;
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedIshitaHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            theta: theta.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedIshitaHmm {
            labels,
            start,
            trans,
            theta,
            loglik,
        })
    }
}

