impl FitUnsupervised for WrappedLogisticHmm {
    type Fitted = FittedWrappedLogisticHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedWrappedLogisticHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        if t_len == 0 {
            return ctx.finish(FittedWrappedLogisticHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                loc: Vector::zeros(k),
                scale: Vector::filled(k, 0.6),
                loglik: f64::NAN,
            });
        }
        let mut loc = Vector::from_iter((0..k).map(|j| -0.35 + 0.70 * j as f64));
        let mut scale = Vector::from_iter((0..k).map(|j| 0.45 + 0.25 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedWrappedLogisticHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                loc: loc.clone(),
                scale: scale.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut sx = 0.0_f64;
                let mut sy = 0.0_f64;
                let mut wsum = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() {
                        continue;
                    }
                    let th = wrap_pi(y);
                    let w = fb.gamma[t][j];
                    sx += w * th.cos();
                    sy += w * th.sin();
                    wsum += w;
                }
                let r2 = sx * sx + sy * sy;
                if r2 > 1e-18 {
                    loc[j] = wrap_pi(sy.atan2(sx));
                    if wsum > 1e-12 {
                        let res = (r2.sqrt() / wsum).clamp(1e-6, 1.0 - 1e-6);
                        scale[j] = ((1.0 - res) / res.max(1e-6)).clamp(0.08, 2.5);
                    }
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedWrappedLogisticHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            loc: loc.clone(),
            scale: scale.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedWrappedLogisticHmm {
            labels,
            start,
            trans,
            loc,
            scale,
            loglik,
        })
    }
}

