impl FitUnsupervised for UnitRiceHmm {
    type Fitted = FittedUnitRiceHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitRiceHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let nu = Vector::from_iter((0..k).map(|j| 0.8 + 0.6 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            let y = x.get(i, 0);
            if y.is_finite() && (y <= 0.0 || y >= 1.0) {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "UnitRiceHmm skipped {n_skip} observations outside (0,1)"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedUnitRiceHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                nu,
                sigma: Vector::filled(k, 1.0),
                loglik: f64::NAN,
            });
        }
        let mut sigma = Vector::from_iter((0..k).map(|j| 0.8 + 0.6 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedUnitRiceHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                nu: nu.clone(),
                sigma: sigma.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wu2 = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 || y >= 1.0 {
                        continue;
                    }
                    let u = y / (1.0 - y);
                    wsum += fb.gamma[t][j];
                    wu2 += fb.gamma[t][j] * u * u;
                }
                if wsum > 1e-12 {
                    let ms = ((wu2 / wsum) - nu[j] * nu[j]).max(1e-4) / 2.0;
                    sigma[j] = ms.sqrt().clamp(0.05, 20.0);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedUnitRiceHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            nu: nu.clone(),
            sigma: sigma.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedUnitRiceHmm {
            labels,
            start,
            trans,
            nu,
            sigma,
            loglik,
        })
    }
}

