impl Predict for FittedKumaraswamyInverseNakagamiHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for KumaraswamyInverseNakagamiHmm {
    type Fitted = FittedKumaraswamyInverseNakagamiHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedKumaraswamyInverseNakagamiHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let shape = Vector::from_iter((0..k).map(|j| 1.25 + 0.35 * j as f64));
        let a = Vector::from_iter((0..k).map(|j| 1.5 + 0.3 * j as f64));
        let b = Vector::from_iter((0..k).map(|j| 2.2 + 0.4 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            if x.get(i, 0).is_finite() && x.get(i, 0) <= 0.0 {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "KumaraswamyInverseNakagamiHmm skipped {n_skip} non-positive observations"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedKumaraswamyInverseNakagamiHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                scale: Vector::filled(k, 0.06),
                shape,
                a,
                b,
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..k).map(|j| 0.06 + 0.03 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedKumaraswamyInverseNakagamiHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                shape: shape.clone(),
                a: a.clone(),
                b: b.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut winv2 = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    winv2 += fb.gamma[t][j] / (y * y);
                }
                if wsum > 1e-12 && winv2 > 1e-18 {
                    scale[j] = (winv2 / wsum).clamp(0.048, 0.14);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedKumaraswamyInverseNakagamiHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            scale: scale.clone(),
            shape: shape.clone(),
            a: a.clone(),
            b: b.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedKumaraswamyInverseNakagamiHmm {
            labels,
            start,
            trans,
            scale,
            shape,
            a,
            b,
            loglik,
        })
    }
}

fn power_lindley_rate_from_moment(s: f64) -> f64 {
    let s = s.max(1e-6);
    let disc = (s - 1.0) * (s - 1.0) + 8.0 * s;
    (1.0 - s + disc.sqrt()) / (2.0 * s)
}

fn power_lindley_cdf(y: f64, theta: f64, alpha: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 || alpha <= 0.0 {
        return 0.0;
    }
    let ya = y.powf(alpha);
    if !ya.is_finite() || ya > 80.0 {
        return 1.0 - 1e-15;
    }
    let surv = (1.0 + theta * ya / (theta + 1.0)) * (-theta * ya).exp();
    if !surv.is_finite() {
        return 0.0;
    }
    (1.0 - surv).clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_pl(y: f64, theta: f64, alpha: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || theta <= 0.0 || alpha <= 0.0 {
        return f64::NEG_INFINITY;
    }
    log_power_lindley(y / (1.0 - y), theta, alpha) - 2.0 * (1.0 - y).ln()
}

fn log_beta_pl(y: f64, theta: f64, alpha: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 || alpha <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = power_lindley_cdf(y, theta, alpha);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_power_lindley(y, theta, alpha) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_pl(y: f64, theta: f64, alpha: f64, power: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 || alpha <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = power_lindley_cdf(y, theta, alpha);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_power_lindley(y, theta, alpha) + (power - 1.0) * cdf.ln()
}

fn log_kuma_pl(y: f64, theta: f64, alpha: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 || alpha <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = power_lindley_cdf(y, theta, alpha);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_power_lindley(y, theta, alpha) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_pl(y: f64, theta: f64, alpha: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || theta <= 0.0 || alpha <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let p = (power_lindley_cdf(kk + 1.0, theta, alpha) - power_lindley_cdf(kk, theta, alpha)).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

/// Unit power-Lindley HMM on \((0,1)\) (power-Lindley on \(u=x/(1-x)\)).
