impl FitUnsupervised for UnitHjorthHmm {
    type Fitted = FittedUnitHjorthHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitHjorthHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let shape = Vector::from_iter((0..k).map(|j| 0.50 + 0.20 * j as f64));
        let theta = Vector::from_iter((0..k).map(|j| 0.80 + 0.30 * j as f64));
let mut n_skip = 0usize;
        for i in 0..t_len {
            let y = x.get(i, 0);
            if y.is_finite() && (y <= 0.0 || y >= 1.0) {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "UnitHjorthHmm skipped {n_skip} observations outside (0,1)"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedUnitHjorthHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                scale: Vector::filled(k, 0.16),
                shape,
                theta,
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..k).map(|j| 0.16 + 0.06 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedUnitHjorthHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                shape: shape.clone(),
                theta: theta.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let bj: f64 = shape[j];
                let tj: f64 = theta[j];
                let mut dj = scale[j];
                for _ in 0..5 {
                    let mut sc = 0.0_f64;
                    let mut hp = 0.0_f64;
                    for t in 0..t_len {
                        let y = x.get(t, 0);
                        if !y.is_finite() || y <= 0.0 || y >= 1.0 {
                            continue;
                        }
                        let z = y / (1.0 - y);
                        if !z.is_finite() || z <= 0.0 {
                            continue;
                        }
                        let den = 1.0 + bj * z;
                        if den <= 1e-12 {
                            continue;
                        }
                        let haz = dj * z + tj / den;
                        if haz > 1e-10 {
                            let w = fb.gamma[t][j];
                            sc += w * (z / haz - 0.5 * z * z);
                            hp -= w * (z * z) / (haz * haz);
                        }
                    }
                    if hp.abs() > 1e-12 {
                        dj = (dj - sc / hp).clamp(0.10, 0.28);
                    }
                }
                scale[j] = dj;
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedUnitHjorthHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            scale: scale.clone(),
            shape: shape.clone(),
            theta: theta.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedUnitHjorthHmm {
            labels,
            start,
            trans,
            scale,
            shape,
            theta,
            loglik,
        })
    }
}

