fn mo_exp_cdf(y: f64, lam: f64, alpha: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || lam <= 0.0 || alpha <= 0.0 || alpha >= 1.0 {
        return 0.0;
    }
    let e = (-lam * y).exp();
    if !e.is_finite() {
        return 1.0 - 1e-15;
    }
    let den = 1.0 - alpha * e;
    if den <= 1e-15 {
        return 1.0 - 1e-15;
    }
    ((1.0 - e) / den).clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_moe(y: f64, lam: f64, alpha: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || lam <= 0.0 || alpha <= 0.0 || alpha >= 1.0 {
        return f64::NEG_INFINITY;
    }
    log_mo_exponential(y / (1.0 - y), lam, alpha) - 2.0 * (1.0 - y).ln()
}

fn log_beta_moe(y: f64, lam: f64, alpha: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || lam <= 0.0 || alpha <= 0.0 || alpha >= 1.0 || a <= 0.0 || b <= 0.0
    {
        return f64::NEG_INFINITY;
    }
    let cdf = mo_exp_cdf(y, lam, alpha);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_mo_exponential(y, lam, alpha) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_moe(y: f64, lam: f64, alpha: f64, power: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || lam <= 0.0 || alpha <= 0.0 || alpha >= 1.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = mo_exp_cdf(y, lam, alpha);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_mo_exponential(y, lam, alpha) + (power - 1.0) * cdf.ln()
}

fn log_kuma_moe(y: f64, lam: f64, alpha: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || lam <= 0.0 || alpha <= 0.0 || alpha >= 1.0 || a <= 0.0 || b <= 0.0
    {
        return f64::NEG_INFINITY;
    }
    let cdf = mo_exp_cdf(y, lam, alpha);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_mo_exponential(y, lam, alpha)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_moe(y: f64, lam: f64, alpha: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || lam <= 0.0 || alpha <= 0.0 || alpha >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let k = y.round().max(1.0);
    let p = (mo_exp_cdf(k + 1.0, lam, alpha) - mo_exp_cdf(k, lam, alpha)).max(0.0);
    if p <= 1e-300 {
        return f64::NEG_INFINITY;
    }
    p.ln()
}

/// Unit Marshall–Olkin exponential HMM on $(0,1)$ (MO-exponential on $u=x/(1-x)$).
///
/// Rate $\lambda$ is free from the MO score; tilt $\alpha\in(0,1)$ is pinned, not identification `p`. Distinct from [`MarshallOlkinExponentialHmm`] (half-line) and [`UnitAdditiveWeibullHmm`].
#[derive(Clone, Debug)]
pub struct UnitMarshallOlkinExponentialHmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for UnitMarshallOlkinExponentialHmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl UnitMarshallOlkinExponentialHmm {
    /// `k`-state UnitMarshallOlkinExponentialHmm.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitMarshallOlkinExponentialHmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted UnitMarshallOlkinExponentialHmm.
#[derive(Clone, Debug)]
pub struct FittedUnitMarshallOlkinExponentialHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Rates \(\lambda_j\).
    pub scale: Vector,
    /// Pinned tilts \(\alpha_j\in(0,1)\).
    pub shape: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedUnitMarshallOlkinExponentialHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_unit_moe(y, self.scale[j], self.shape[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedUnitMarshallOlkinExponentialHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for UnitMarshallOlkinExponentialHmm {
    type Fitted = FittedUnitMarshallOlkinExponentialHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitMarshallOlkinExponentialHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let shape = Vector::from_iter((0..k).map(|j| 0.25 + 0.18 * j as f64));
let mut n_skip = 0usize;
        for i in 0..t_len {
            let y = x.get(i, 0);
            if y.is_finite() && (y <= 0.0 || y >= 1.0) {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "UnitMarshallOlkinExponentialHmm skipped {n_skip} observations outside (0,1)"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedUnitMarshallOlkinExponentialHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                scale: Vector::filled(k, 0.70),
                shape,
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..k).map(|j| 0.70 + 0.12 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedUnitMarshallOlkinExponentialHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                shape: shape.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let aj: f64 = shape[j];
                let mut lj = scale[j];
                for _ in 0..5 {
                    let mut sc = 0.0_f64;
                    let mut hp = 0.0_f64;
                    for t in 0..t_len {
                        let y = x.get(t, 0);
                        if !y.is_finite() || y <= 0.0 || y >= 1.0 {
                            continue;
                        }
                        let z = y / (1.0 - y);
                        if !z.is_finite() || z <= 0.0 {
                            continue;
                        }
                        let e = (-lj * z).exp();
                        let den = 1.0 - aj * e;
                        if den <= 1e-10 {
                            continue;
                        }
                        let w = fb.gamma[t][j];
                        let num = aj * z * e;
                        sc += w * (1.0 / lj - z - 2.0 * num / den);
                        hp += w
                            * (-1.0 / (lj * lj)
                                - 2.0 * (aj * z * z * e * (den - aj * e)) / (den * den));
                    }
                    if hp.abs() > 1e-12 {
                        lj = (lj - sc / hp).clamp(0.55, 0.90);
                    }
                }
                scale[j] = lj;
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedUnitMarshallOlkinExponentialHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            scale: scale.clone(),
            shape: shape.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedUnitMarshallOlkinExponentialHmm {
            labels,
            start,
            trans,
            scale,
            shape,
            loglik,
        })
    }
}

