fn mo_weibull_cdf(y: f64, shape: f64, scale: f64, tilt: f64) -> f64 {
    if !y.is_finite()
        || y <= 0.0
        || shape <= 0.0
        || scale <= 0.0
        || tilt <= 0.0
        || tilt >= 1.0
    {
        return 0.0;
    }
    let z = (y / scale).powf(shape);
    if !z.is_finite() || z > 40.0 {
        return 1.0 - 1e-15;
    }
    let s0 = (-z).exp();
    if !s0.is_finite() {
        return 1.0 - 1e-15;
    }
    let den = 1.0 - (1.0 - tilt) * s0;
    if den <= 1e-15 {
        return 1.0 - 1e-15;
    }
    ((1.0 - s0) / den).clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_mow(y: f64, shape: f64, scale: f64, tilt: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || shape <= 0.0 || scale <= 0.0 || tilt <= 0.0 || tilt >= 1.0
    {
        return f64::NEG_INFINITY;
    }
    log_mo_weibull(y / (1.0 - y), shape, scale, tilt) - 2.0 * (1.0 - y).ln()
}

fn log_beta_mow(y: f64, shape: f64, scale: f64, tilt: f64, alpha: f64, beta: f64) -> f64 {
    if !y.is_finite()
        || y <= 0.0
        || shape <= 0.0
        || scale <= 0.0
        || tilt <= 0.0
        || tilt >= 1.0
        || alpha <= 0.0
        || beta <= 0.0
    {
        return f64::NEG_INFINITY;
    }
    let cdf = mo_weibull_cdf(y, shape, scale, tilt);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_mo_weibull(y, shape, scale, tilt) + (alpha - 1.0) * cdf.ln() + (beta - 1.0) * surv.ln()
        - ln_beta(alpha, beta)
}

fn log_exp_mow(y: f64, shape: f64, scale: f64, tilt: f64, power: f64) -> f64 {
    if !y.is_finite()
        || y <= 0.0
        || shape <= 0.0
        || scale <= 0.0
        || tilt <= 0.0
        || tilt >= 1.0
        || power <= 0.0
    {
        return f64::NEG_INFINITY;
    }
    let cdf = mo_weibull_cdf(y, shape, scale, tilt);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_mo_weibull(y, shape, scale, tilt) + (power - 1.0) * cdf.ln()
}

fn log_kuma_mow(y: f64, shape: f64, scale: f64, tilt: f64, alpha: f64, beta: f64) -> f64 {
    if !y.is_finite()
        || y <= 0.0
        || shape <= 0.0
        || scale <= 0.0
        || tilt <= 0.0
        || tilt >= 1.0
        || alpha <= 0.0
        || beta <= 0.0
    {
        return f64::NEG_INFINITY;
    }
    let cdf = mo_weibull_cdf(y, shape, scale, tilt);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(alpha);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    alpha.ln()
        + beta.ln()
        + log_mo_weibull(y, shape, scale, tilt)
        + (alpha - 1.0) * cdf.ln()
        + (beta - 1.0) * one_m.ln()
}

fn log_disc_mow(y: f64, shape: f64, scale: f64, tilt: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || shape <= 0.0 || scale <= 0.0 || tilt <= 0.0 || tilt >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let k = y.round().max(1.0);
    let p = (mo_weibull_cdf(k + 1.0, shape, scale, tilt) - mo_weibull_cdf(k, shape, scale, tilt))
        .max(0.0);
    if p <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    p.ln()
}

/// Unit Marshall–Olkin Weibull HMM on $(0,1)$ (MO-Weibull on $u=x/(1-x)$).
///
/// Scale $\lambda$ is free from $\mathbb{E}[U]$; shape $k\neq 1$ and tilt $\alpha\in(0,1)$ are pinned, not identification `p`. Distinct from [`MarshallOlkinWeibullHmm`] (half-line) and [`UnitWeibullHmm`].
#[derive(Clone, Debug)]
pub struct UnitMarshallOlkinWeibullHmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for UnitMarshallOlkinWeibullHmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl UnitMarshallOlkinWeibullHmm {
    /// `k`-state UnitMarshallOlkinWeibullHmm.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitMarshallOlkinWeibullHmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted UnitMarshallOlkinWeibullHmm.
#[derive(Clone, Debug)]
pub struct FittedUnitMarshallOlkinWeibullHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Weibull scales \(\lambda_j\).
    pub scale: Vector,
    /// Pinned Weibull shapes \(k_j\neq 1\).
    pub shape: Vector,
    /// Pinned Marshall–Olkin tilts \(\alpha_j\in(0,1)\).
    pub tilt: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedUnitMarshallOlkinWeibullHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_unit_mow(y, self.shape[j], self.scale[j], self.tilt[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedUnitMarshallOlkinWeibullHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for UnitMarshallOlkinWeibullHmm {
    type Fitted = FittedUnitMarshallOlkinWeibullHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitMarshallOlkinWeibullHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let shape = Vector::from_iter((0..k).map(|j| 1.25 + 0.20 * j as f64));
        let tilt = Vector::from_iter((0..k).map(|j| 0.30 + 0.18 * j as f64));
let mut n_skip = 0usize;
        for i in 0..t_len {
            let y = x.get(i, 0);
            if y.is_finite() && (y <= 0.0 || y >= 1.0) {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "UnitMarshallOlkinWeibullHmm skipped {n_skip} observations outside (0,1)"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedUnitMarshallOlkinWeibullHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                scale: Vector::filled(k, 1.50),
                shape,
                tilt,
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..k).map(|j| 1.50 + 0.35 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedUnitMarshallOlkinWeibullHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                shape: shape.clone(),
                tilt: tilt.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wy = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 || y >= 1.0 {
                        continue;
                    }
                    let z = y / (1.0 - y);
                    if !z.is_finite() || z <= 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    wy += fb.gamma[t][j] * z;
                }
                if wsum > 1e-12 {
                    scale[j] = (wy / wsum).clamp(1.00, 2.80);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedUnitMarshallOlkinWeibullHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            scale: scale.clone(),
            shape: shape.clone(),
            tilt: tilt.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedUnitMarshallOlkinWeibullHmm {
            labels,
            start,
            trans,
            scale,
            shape,
            tilt,
            loglik,
        })
    }
}

