/// Fitted DiscreteMarshallOlkinWeibullHmm.
#[derive(Clone, Debug)]
pub struct FittedDiscreteMarshallOlkinWeibullHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Weibull scales \(\lambda_j\).
    pub scale: Vector,
    /// Pinned Weibull shapes \(k_j\neq 1\).
    pub shape: Vector,
    /// Pinned Marshall–Olkin tilts \(\alpha_j\in(0,1)\).
    pub tilt: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedDiscreteMarshallOlkinWeibullHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_disc_mow(y, self.shape[j], self.scale[j], self.tilt[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

