fn burr_g_cdf(y: f64, scale: f64, c: f64, k: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || scale <= 0.0 || c <= 0.0 || k <= 0.0 {
        return 0.0;
    }
    let z = (y / scale).powf(c);
    if !z.is_finite() {
        return if y > scale { 1.0 - 1e-15 } else { 0.0 };
    }
    (1.0 - (1.0 + z).powf(-k)).clamp(0.0, 1.0 - 1e-15)
}

fn log_beta_bu(y: f64, scale: f64, c: f64, k: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || scale <= 0.0 || c <= 0.0 || k <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = burr_g_cdf(y, scale, c, k);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_burr(y, scale, c, k) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_bu(y: f64, scale: f64, c: f64, k: f64, power: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || scale <= 0.0 || c <= 0.0 || k <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = burr_g_cdf(y, scale, c, k);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_burr(y, scale, c, k) + (power - 1.0) * cdf.ln()
}

fn log_kuma_bu(y: f64, scale: f64, c: f64, k: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || scale <= 0.0 || c <= 0.0 || k <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = burr_g_cdf(y, scale, c, k);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_burr(y, scale, c, k)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}


