fn igam_g_cdf(y: f64, shape: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || shape <= 0.0 || scale <= 0.0 {
        return 0.0;
    }
    let z = scale / y;
    if !z.is_finite() {
        return if y > scale { 1.0 - 1e-15 } else { 0.0 };
    }
    (1.0 - crate::special::gamma_p(shape, z)).clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_igam(y: f64, shape: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || shape <= 0.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u <= 0.0 {
        return f64::NEG_INFINITY;
    }
    log_invgamma(u, shape, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_igam(y: f64, shape: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || shape <= 0.0 || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = igam_g_cdf(y, shape, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_invgamma(y, shape, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_igam(y: f64, shape: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || shape <= 0.0 || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = igam_g_cdf(y, shape, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_invgamma(y, shape, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_igam(y: f64, shape: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || shape <= 0.0 || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = igam_g_cdf(y, shape, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_invgamma(y, shape, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}


/// Unit inverse-gamma HMM (inverse-gamma on the odds $y/(1-y)$).
///
/// Scale is free from $\alpha/\mathbb{E}[1/Y]$; inverse-gamma shape $\alpha\neq 1$ is pinned, not identification `p`. Distinct from [`InverseGammaHmm`] and [`DiscreteInverseGammaHmm`].
