fn fn_g_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 {
        return 0.0;
    }
    let z1 = (y - loc) / scale;
    let z2 = (y + loc) / scale;
    if !z1.is_finite() || !z2.is_finite() {
        return if y > loc.abs() { 1.0 - 1e-15 } else { 0.0 };
    }
    (crate::special::norm_cdf(z1) + crate::special::norm_cdf(z2) - 1.0).clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_fn(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_folded_normal(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_fn(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = fn_g_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_folded_normal(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_fn(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = fn_g_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_folded_normal(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_fn(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = fn_g_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_folded_normal(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_fn(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = fn_g_cdf(kk, loc, scale);
    let hi = fn_g_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

/// Unit folded-normal HMM (folded normal on the odds $y/(1-y)$).
///
/// Scale is free from $\sqrt{\mathbb{E}[U^2]-\mu^2}$; location $\mu\neq 0$ is pinned, not identification `p`. Distinct from [`FoldedNormalHmm`] and [`UnitHalfNormalHmm`].
#[derive(Clone, Debug)]
pub struct UnitFoldedNormalHmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for UnitFoldedNormalHmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl UnitFoldedNormalHmm {
    /// `k`-state UnitFoldedNormalHmm.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitFoldedNormalHmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted UnitFoldedNormalHmm.
#[derive(Clone, Debug)]
pub struct FittedUnitFoldedNormalHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Free folded-normal scales from $\sqrt{\mathbb{E}[Y^2]-\mu^2}$.
    pub scale: Vector,
    /// Pinned pre-fold locations $\mu_j\neq 0$.
    pub loc: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedUnitFoldedNormalHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_unit_fn(y, self.loc[j], self.scale[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

