        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_beta_jsl(y, self.xi[j], self.scale[j].ln(), self.sigma[j] * self.sigma[j], self.a[j], self.b[j]);
            }
        }
        out
