fn log_folded_logistic(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    logsumexp(&[log_logistic(y, loc, scale), log_logistic(y, -loc, scale)])
}

fn fl_logistic_cdf(z: f64) -> f64 {
    if !z.is_finite() {
        return if z > 0.0 { 1.0 } else { 0.0 };
    }
    let e = (-z.clamp(-40.0, 40.0)).exp();
    1.0 / (1.0 + e)
}

fn fl_g_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 {
        return 0.0;
    }
    (fl_logistic_cdf((y - loc) / scale) + fl_logistic_cdf((y + loc) / scale) - 1.0)
        .clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_fl(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_folded_logistic(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_fl(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = fl_g_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_folded_logistic(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_fl(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = fl_g_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_folded_logistic(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_fl(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = fl_g_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_folded_logistic(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_fl(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = fl_g_cdf(kk, loc, scale);
    let hi = fl_g_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

