pub struct FittedBetaFoldedLogisticHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Free folded-logistic scales from $\exp(\mathbb{E}[\ln Y])$.
    pub scale: Vector,
    /// Pinned pre-fold locations $\mu_j\neq 0$.
    pub loc: Vector,
    /// First extra shapes $a_j\neq 1$.
    pub a: Vector,
    /// Second extra shapes $b_j\neq 1$.
    pub b: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedBetaFoldedLogisticHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_beta_fl(y, self.loc[j], self.scale[j], self.a[j], self.b[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedBetaFoldedLogisticHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for BetaFoldedLogisticHmm {
    type Fitted = FittedBetaFoldedLogisticHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedBetaFoldedLogisticHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let loc = Vector::from_iter((0..k).map(|j| 1.40 + 0.15 * j as f64));
        let a = Vector::from_iter((0..k).map(|j| 1.35 + 0.25 * j as f64));
        let b = Vector::from_iter((0..k).map(|j| 1.55 + 0.20 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            let y = x.get(i, 0);
            if y.is_finite() && (y < 0.0) {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "BetaFoldedLogisticHmm skipped {n_skip} negative observations"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedBetaFoldedLogisticHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                scale: Vector::filled(k, 3.50),
                loc,
                a,
                b,
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..k).map(|j| 3.50 + 0.80 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedBetaFoldedLogisticHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                a: a.clone(),
                b: b.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wln = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 {
                        continue;
                    }
                    let z = y;
                    wsum += fb.gamma[t][j];
                    wln += fb.gamma[t][j] * z.ln();
                }
                if wsum > 1e-12 {
                    let hat = (wln / wsum).exp();
                    if hat.is_finite() && hat > 0.0 {
                        scale[j] = hat.clamp(2.00, 6.50);
                    }
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedBetaFoldedLogisticHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                a: a.clone(),
                b: b.clone(),
                loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedBetaFoldedLogisticHmm {
            labels,
            start,
            trans,
            scale,
            loc,
            a,
            b,
            loglik,
        })
    }
}

/// Exponentiated folded-logistic HMM ($a f F^{a-1}$, $a\neq 1$).
///
/// Scale is free from $\exp(\mathbb{E}[\ln Y])$; location $\mu\neq 0$ is pinned, not identification `p`. Distinct from [`KumaraswamyFoldedLogisticHmm`] and [`DiscreteFoldedLogisticHmm`].
#[derive(Clone, Debug)]
pub struct ExponentiatedFoldedLogisticHmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for ExponentiatedFoldedLogisticHmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl ExponentiatedFoldedLogisticHmm {
    /// `k`-state ExponentiatedFoldedLogisticHmm.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedExponentiatedFoldedLogisticHmm>> {
        self.fit_unsupervised(x, session)
    }
}

