fn log_folded_sech(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    logsumexp(&[
        log_hyperbolic_secant(y, loc, scale),
        log_hyperbolic_secant(y, -loc, scale),
    ])
}

fn fhs_sech_cdf(z: f64) -> f64 {
    if !z.is_finite() {
        return if z > 0.0 { 1.0 } else { 0.0 };
    }
    let z = z.clamp(-40.0, 40.0);
    let e = (0.5 * std::f64::consts::PI * z).exp();
    if !e.is_finite() {
        return if z > 0.0 { 1.0 } else { 0.0 };
    }
    (2.0 / std::f64::consts::PI) * e.atan()
}

fn fhs_g_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 {
        return 0.0;
    }
    (fhs_sech_cdf((y - loc) / scale) + fhs_sech_cdf((y + loc) / scale) - 1.0).clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_fhs(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_folded_sech(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_fhs(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = fhs_g_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_folded_sech(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_fhs(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = fhs_g_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_folded_sech(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_fhs(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = fhs_g_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_folded_sech(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_fhs(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = fhs_g_cdf(kk, loc, scale);
    let hi = fhs_g_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

