/// Fitted DiscreteFoldedMoyalHmm.
#[derive(Clone, Debug)]
pub struct FittedDiscreteFoldedMoyalHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Free folded-Moyal scales from $\exp(\mathbb{E}[\ln Y])$.
    pub scale: Vector,
    /// Pinned pre-fold locations $\mu_j\neq 0$.
    pub loc: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedDiscreteFoldedMoyalHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_disc_fm(y, self.loc[j], self.scale[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedDiscreteFoldedMoyalHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for DiscreteFoldedMoyalHmm {
    type Fitted = FittedDiscreteFoldedMoyalHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedDiscreteFoldedMoyalHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let loc = Vector::from_iter((0..k).map(|j| 0.15 + 0.05 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            let y = x.get(i, 0);
            if y.is_finite() && (y < 1.0) {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "DiscreteFoldedMoyalHmm skipped {n_skip} observations below 1"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedDiscreteFoldedMoyalHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                scale: Vector::filled(k, 2.20),
                loc,
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..k).map(|j| 2.20 + 0.60 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedDiscreteFoldedMoyalHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wln = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y < 1.0 {
                        continue;
                    }
                    let z = y;
                    wsum += fb.gamma[t][j];
                    wln += fb.gamma[t][j] * z.ln();
                }
                if wsum > 1e-12 {
                    let hat = (wln / wsum).exp();
                    if hat.is_finite() && hat > 0.0 {
                        scale[j] = hat.clamp(1.20, 5.50);
                    }
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedDiscreteFoldedMoyalHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedDiscreteFoldedMoyalHmm {
            labels,
            start,
            trans,
            scale,
            loc,
            loglik,
        })
    }
}


fn slash_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let z = (y - loc) / scale;
    let inv_sqrt_2pi = (-0.5 * LN_2PI).exp();
    if z.abs() < 1e-6 {
        return (0.5 + 0.5 * z * inv_sqrt_2pi).clamp(0.0, 1.0 - 1e-15);
    }
    let phiz = (-0.5 * z * z).exp() * inv_sqrt_2pi;
    (crate::special::norm_cdf(z) - (inv_sqrt_2pi - phiz) / z).clamp(0.0, 1.0 - 1e-15)
}

fn log_folded_slash(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    // Asymmetric when μ≠0: f(|X|=y) = f(y)+f(-y).
    logsumexp(&[log_slash(y, loc, scale), log_slash(-y, loc, scale)])
}

fn fs_g_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 {
        return 0.0;
    }
    (slash_cdf(y, loc, scale) - slash_cdf(-y, loc, scale)).clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_fs(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_folded_slash(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_fs(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = fs_g_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_folded_slash(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_fs(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = fs_g_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_folded_slash(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_fs(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = fs_g_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_folded_slash(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_fs(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = fs_g_cdf(kk, loc, scale);
    let hi = fs_g_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

