fn log_triweight(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let z = (y - loc) / scale;
    if z.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let w = 1.0 - z * z;
    let dens = (35.0 / (32.0 * scale)) * w * w * w;
    dens.max(1e-15).ln()
}

fn triweight_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let z = (y - loc) / scale;
    if z <= -1.0 {
        return 0.0;
    }
    if z >= 1.0 {
        return 1.0 - 1e-15;
    }
    let z2 = z * z;
    let z3 = z2 * z;
    let z5 = z3 * z2;
    let z7 = z5 * z2;
    (0.5 + (35.0 / 32.0) * z - (35.0 / 32.0) * z3 + (21.0 / 32.0) * z5 - (5.0 / 32.0) * z7)
        .clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_tw(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_triweight(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_tw(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = triweight_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_triweight(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_tw(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = triweight_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_triweight(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_tw(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = triweight_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_triweight(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_tw(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = triweight_cdf(kk, loc, scale);
    let hi = triweight_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

/// Unit triweight HMM (triweight kernel on the odds $y/(1-y)$).
///
/// Half-width is free and expanded to cover every odds value; location $\mu$ sits below the sample and is not identification `p`. Distinct from [`UnitQuarticHmm`] (biweight) and [`UnitEpanechnikovHmm`].
