fn irwin_hall3_cdf(x: f64) -> f64 {
    if !x.is_finite() || x <= 0.0 {
        return 0.0;
    }
    if x >= 3.0 {
        return 1.0 - 1e-15;
    }
    let kmax = (x.floor() as i32).min(3);
    let mut s = 0.0_f64;
    for k in 0..=kmax {
        let sign = if k % 2 == 0 { 1.0 } else { -1.0 };
        let c = match k {
            0 => 1.0,
            1 => 3.0,
            2 => 3.0,
            3 => 1.0,
            _ => 0.0,
        };
        s += sign * c * (x - k as f64).max(0.0).powi(3);
    }
    (s / 6.0).clamp(0.0, 1.0 - 1e-15)
}

fn bates3_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let lo = loc - scale;
    let hi = loc + scale;
    if y <= lo {
        return 0.0;
    }
    if y >= hi {
        return 1.0 - 1e-15;
    }
    irwin_hall3_cdf(3.0 * (y - lo) / (hi - lo))
}

fn log_unit_bt(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_bates(u, loc - scale, loc + scale, 3) - 2.0 * (1.0 - y).ln()
}

fn log_beta_bt(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = bates3_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_bates(y, loc - scale, loc + scale, 3) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln()
        - ln_beta(a, b)
}

fn log_exp_bt(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = bates3_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_bates(y, loc - scale, loc + scale, 3) + (power - 1.0) * cdf.ln()
}

fn log_kuma_bt(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = bates3_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_bates(y, loc - scale, loc + scale, 3)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_bt(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = bates3_cdf(kk, loc, scale);
    let hi = bates3_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

/// Unit Bates HMM (Irwin–Hall $n=3$ on the odds $y/(1-y)$).
