        for i in 0..t_len {
            let y = x.get(i, 0);
            if y.is_finite() && (y < 0.0) {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "BetaTsp13Hmm skipped {n_skip} negative observations"
                    ))
                    .build(),
            );
        }
