fn log_cos21(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = (y - loc) / scale;
    if u.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let c = (std::f64::consts::PI * u / 2.0).cos();
    if c <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let c2 = c * c;
    let c4 = c2 * c2;
    let dens = (969969.0 * std::f64::consts::PI / (1048576.0 * scale)) * c4 * c4 * c4 * c4 * c4 * c;
    dens.max(1e-15).ln()
}

fn cos21_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    let s = (std::f64::consts::PI * u / 2.0).sin();
    let s2 = s * s;
    let s3 = s * s2;
    let s5 = s3 * s2;
    let s7 = s5 * s2;
    let s9 = s7 * s2;
    let s11 = s9 * s2;
    let s13 = s11 * s2;
    let s15 = s13 * s2;
    let s17 = s15 * s2;
    let s19 = s17 * s2;
    let s21 = s19 * s2;
    (0.5 + (969969.0 / 524288.0) * s - (1616615.0 / 262144.0) * s3 + (8729721.0 / 524288.0) * s5
        - (2078505.0 / 65536.0) * s7 + (11316305.0 / 262144.0) * s9 - (5555277.0 / 131072.0) * s11
        + (7834365.0 / 262144.0) * s13 - (969969.0 / 65536.0) * s15 + (2567565.0 / 524288.0) * s17
        - (255255.0 / 262144.0) * s19 + (46189.0 / 524288.0) * s21)
        .clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_c21(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_cos21(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_c21(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos21_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_cos21(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_c21(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos21_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_cos21(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_c21(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos21_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_cos21(y, loc, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_c21(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = cos21_cdf(kk, loc, scale);
    let hi = cos21_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}
/// Unit cosine-twenty-first HMM ($f\propto\cos^{21}(\pi u/2)$ on the odds $y/(1-y)$, $|u|<1$).
