fn log_cos22(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = (y - loc) / scale;
    if u.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let c = (std::f64::consts::PI * u / 2.0).cos();
    if c <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let c2 = c * c;
    let c4 = c2 * c2;
    let dens = (262144.0 / (88179.0 * scale)) * c4 * c4 * c4 * c4 * c4 * c2;
    dens.max(1e-15).ln()
}

fn cos22_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    let th = std::f64::consts::PI * u / 2.0;
    let pi = std::f64::consts::PI;
    (0.5
        + th / pi
        + (11.0 / (12.0 * pi)) * (2.0 * th).sin()
        + (55.0 / (156.0 * pi)) * (4.0 * th).sin()
        + (55.0 / (364.0 * pi)) * (6.0 * th).sin()
        + (11.0 / (182.0 * pi)) * (8.0 * th).sin()
        + (11.0 / (520.0 * pi)) * (10.0 * th).sin()
        + (11.0 / (1768.0 * pi)) * (12.0 * th).sin()
        + (55.0 / (37128.0 * pi)) * (14.0 * th).sin()
        + (55.0 / (201552.0 * pi)) * (16.0 * th).sin()
        + (11.0 / (302328.0 * pi)) * (18.0 * th).sin()
        + (11.0 / (3527160.0 * pi)) * (20.0 * th).sin()
        + (1.0 / (7759752.0 * pi)) * (22.0 * th).sin())
        .clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_c22(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_cos22(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_c22(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos22_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_cos22(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_c22(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos22_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_cos22(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_c22(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos22_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_cos22(y, loc, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_c22(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = cos22_cdf(kk, loc, scale);
    let hi = cos22_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}
/// Unit cosine-twenty-second HMM ($f\propto\cos^{22}(\pi u/2)$ on the odds $y/(1-y)$, $|u|<1$).
