fn log_cos30(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = (y - loc) / scale;
    if u.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let c = (std::f64::consts::PI * u / 2.0).cos();
    if c <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let c2 = c * c;
    let c4 = c2 * c2;
    let dens = (33554432.0 / (9694845.0 * scale)) * c4 * c4 * c4 * c4 * c4 * c4 * c4 * c2;
    dens.max(1e-15).ln()
}

fn cos30_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    let th = std::f64::consts::PI * u / 2.0;
    let pi = std::f64::consts::PI;
    (0.5
        + th / pi
        + (15.0 / (16.0 * pi)) * (2.0 * th).sin()
        + (105.0 / (272.0 * pi)) * (4.0 * th).sin()
        + (455.0 / (2448.0 * pi)) * (6.0 * th).sin()
        + (455.0 / (5168.0 * pi)) * (8.0 * th).sin()
        + (1001.0 / (25840.0 * pi)) * (10.0 * th).sin()
        + (715.0 / (46512.0 * pi)) * (12.0 * th).sin()
        + (195.0 / (36176.0 * pi)) * (14.0 * th).sin()
        + (195.0 / (118864.0 * pi)) * (16.0 * th).sin()
        + (455.0 / (1069776.0 * pi)) * (18.0 * th).sin()
        + (273.0 / (2971600.0 * pi)) * (20.0 * th).sin()
        + (21.0 / (1307504.0 * pi)) * (22.0 * th).sin()
        + (7.0 / (3209328.0 * pi)) * (24.0 * th).sin()
        + (1.0 / (4635696.0 * pi)) * (26.0 * th).sin()
        + (1.0 / (72388176.0 * pi)) * (28.0 * th).sin()
        + (1.0 / (2326762800.0 * pi)) * (30.0 * th).sin())
        .clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_c30(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_cos30(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_c30(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos30_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_cos30(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_c30(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos30_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_cos30(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_c30(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos30_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_cos30(y, loc, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_c30(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = cos30_cdf(kk, loc, scale);
    let hi = cos30_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}
/// Unit cosine-thirtieth HMM ($f\propto\cos^{30}(\pi u/2)$ on the odds $y/(1-y)$, $|u|<1$).
