fn log_tsp41(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = (y - loc) / scale;
    if u.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let dens = (20.5 / scale) * (1.0 - u.abs()).powi(40);
    dens.max(1e-15).ln()
}

fn tsp41_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    if u < 0.0 {
        (0.5 * (1.0 + u).powi(41)).clamp(0.0, 1.0 - 1e-15)
    } else {
        (1.0 - 0.5 * (1.0 - u).powi(41)).clamp(0.0, 1.0 - 1e-15)
    }
}

fn log_unit_s41(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_tsp41(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_s41(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = tsp41_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_tsp41(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_s41(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = tsp41_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_tsp41(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_s41(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = tsp41_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_tsp41(y, loc, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_s41(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = tsp41_cdf(kk, loc, scale);
    let hi = tsp41_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

/// Unit two-sided-power HMM (shape $n=41$, $f\propto(1-|u|)^40$ on the odds $y/(1-y)$).
///
/// Half-width is free and expanded to cover every odds value; location $\mu$ sits below the sample and is not identification `p`. Distinct from [`UnitTsp40Hmm`] ($n=40$).
#[derive(Clone, Debug)]
pub struct UnitTsp41Hmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for UnitTsp41Hmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl UnitTsp41Hmm {
    /// `k`-state UnitTsp41Hmm.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitTsp41Hmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted UnitTsp41Hmm.
#[derive(Clone, Debug)]
pub struct FittedUnitTsp41Hmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Free half-width expanded to cover every observation.
    pub scale: Vector,
    /// Pinned locations below the sample (not identification `p`).
    pub loc: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedUnitTsp41Hmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_unit_s41(y, self.loc[j], self.scale[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedUnitTsp41Hmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for UnitTsp41Hmm {
    type Fitted = FittedUnitTsp41Hmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitTsp41Hmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let loc = Vector::from_iter((0..k).map(|j| -0.20 - 0.05 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            let y = x.get(i, 0);
            if y.is_finite() && (y <= 0.0 || y >= 1.0) {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "UnitTsp41Hmm skipped {n_skip} observations outside (0,1)"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedUnitTsp41Hmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                scale: Vector::filled(k, 5.00),
                loc,
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..k).map(|j| 5.00 + 0.40 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedUnitTsp41Hmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut mx = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 || y >= 1.0 {
                        continue;
                    }
                    let z = y / (1.0 - y);
                    if !z.is_finite() || z <= 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    mx = mx.max((z - loc[j]).abs());
                }
                if wsum > 1e-12 {
                    scale[j] = (mx * 1.4 + 2.5).clamp(0.80, 40.00);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedUnitTsp41Hmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedUnitTsp41Hmm {
            labels,
            start,
            trans,
            scale,
            loc,
            loglik,
        })
    }
}

