fn log_cos37(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = (y - loc) / scale;
    if u.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let c = (std::f64::consts::PI * u / 2.0).cos();
    if c <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let c2 = c * c;
    let c4 = c2 * c2;
    let dens = (83945001525.0 * std::f64::consts::PI / (68719476736.0 * scale)) * c4 * c4 * c4 * c4 * c4 * c4 * c4 * c4 * c4 * c;
    dens.max(1e-15).ln()
}

fn cos37_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    let s = (std::f64::consts::PI * u / 2.0).sin();
    let s2 = s * s;
    let s3 = s * s2;
    let s5 = s3 * s2;
    let s7 = s5 * s2;
    let s9 = s7 * s2;
    let s11 = s9 * s2;
    let s13 = s11 * s2;
    let s15 = s13 * s2;
    let s17 = s15 * s2;
    let s19 = s17 * s2;
    let s21 = s19 * s2;
    let s23 = s21 * s2;
    let s25 = s23 * s2;
    let s27 = s25 * s2;
    let s29 = s27 * s2;
    let s31 = s29 * s2;
    let s33 = s31 * s2;
    let s35 = s33 * s2;
    let s37 = s35 * s2;
    (0.5 + (83945001525.0 / 34359738368.0) * s - (251835004575.0 / 17179869184.0) * s3
        + (2568717046665.0 / 34359738368.0) * s5 - (611599296825.0 / 2147483648.0) * s7
        + (7135325129625.0 / 8589934592.0) * s9 - (8173190603025.0 / 4294967296.0) * s11
        + (29968365544425.0 / 8589934592.0) * s13 - (11131107202215.0 / 2147483648.0) * s15
        + (108037216962675.0 / 17179869184.0) * s17 - (53702710186125.0 / 8589934592.0) * s19
        + (87458699445975.0 / 17179869184.0) * s21 - (7259417740575.0 / 2147483648.0) * s23
        + (15583550083101.0 / 8589934592.0) * s25 - (3329818393825.0 / 4294967296.0) * s27
        + (2214411247125.0 / 8589934592.0) * s29 - (138103067025.0 / 2147483648.0) * s31
        + (389199552525.0 / 34359738368.0) * s33 - (21585857535.0 / 17179869184.0) * s35
        + (2268783825.0 / 34359738368.0) * s37)
        .clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_c37(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_cos37(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_c37(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos37_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_cos37(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_c37(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos37_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_cos37(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_c37(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos37_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_cos37(y, loc, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_c37(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = cos37_cdf(kk, loc, scale);
    let hi = cos37_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}
/// Unit cosine-thirty-seventh HMM ($f\propto\cos^{37}(\pi u/2)$ on the odds $y/(1-y)$, $|u|<1$).
