fn log_cos39(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = (y - loc) / scale;
    if u.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let c = (std::f64::consts::PI * u / 2.0).cos();
    if c <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let c2 = c * c;
    let c4 = c2 * c2;
    let dens = (172308161025.0 * std::f64::consts::PI / (137438953472.0 * scale)) * c4 * c4 * c4 * c4 * c4 * c4 * c4 * c4 * c4 * c2 * c;
    dens.max(1e-15).ln()
}

fn cos39_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    let s = (std::f64::consts::PI * u / 2.0).sin();
    let s2 = s * s;
    let s3 = s * s2;
    let s5 = s3 * s2;
    let s7 = s5 * s2;
    let s9 = s7 * s2;
    let s11 = s9 * s2;
    let s13 = s11 * s2;
    let s15 = s13 * s2;
    let s17 = s15 * s2;
    let s19 = s17 * s2;
    let s21 = s19 * s2;
    let s23 = s21 * s2;
    let s25 = s23 * s2;
    let s27 = s25 * s2;
    let s29 = s27 * s2;
    let s31 = s29 * s2;
    let s33 = s31 * s2;
    let s35 = s33 * s2;
    let s37 = s35 * s2;
    let s39 = s37 * s2;
    (0.5 + (172308161025.0 / 68719476736.0) * s - (1091285019825.0 / 68719476736.0) * s3
        + (5892939107055.0 / 68719476736.0) * s5 - (23852372576175.0 / 68719476736.0) * s7
        + (18551845337025.0 / 17179869184.0) * s9 - (45536347645425.0 / 17179869184.0) * s11
        + (89905096633275.0 / 17179869184.0) * s13 - (144704393628795.0 / 17179869184.0) * s15
        + (383041041958575.0 / 34359738368.0) * s17 - (418881139451775.0 / 34359738368.0) * s19
        + (378987697599225.0 / 34359738368.0) * s21 - (283117291882425.0 / 34359738368.0) * s23
        + (86822636177277.0 / 17179869184.0) * s25 - (43287639119725.0 / 17179869184.0) * s27
        + (17272407727575.0 / 17179869184.0) * s29 - (5386019613975.0 / 17179869184.0) * s31
        + (5059594182825.0 / 68719476736.0) * s33 - (841848443865.0 / 68719476736.0) * s35
        + (88482569175.0 / 68719476736.0) * s37 - (4418157975.0 / 68719476736.0) * s39)
        .clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_c39(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_cos39(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_c39(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos39_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_cos39(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_c39(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos39_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_cos39(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_c39(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos39_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_cos39(y, loc, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_c39(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = cos39_cdf(kk, loc, scale);
    let hi = cos39_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}
