fn log_cos40(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = (y - loc) / scale;
    if u.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let c = (std::f64::consts::PI * u / 2.0).cos();
    if c <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let c2 = c * c;
    let c4 = c2 * c2;
    let dens = (137438953472.0 / (34461632205.0 * scale))
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4;
    dens.max(1e-15).ln()
}

fn cos40_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    let th = std::f64::consts::PI * u / 2.0;
    let pi = std::f64::consts::PI;
    (0.5
        + th / pi
        + (20.0 / (21.0 * pi)) * (2.0 * th).sin()
        + (95.0 / (231.0 * pi)) * (4.0 * th).sin()
        + (380.0 / (1771.0 * pi)) * (6.0 * th).sin()
        + (1615.0 / (14168.0 * pi)) * (8.0 * th).sin()
        + (2584.0 / (44275.0 * pi)) * (10.0 * th).sin()
        + (646.0 / (23023.0 * pi)) * (12.0 * th).sin()
        + (2584.0 / (207207.0 * pi)) * (14.0 * th).sin()
        + (323.0 / (63756.0 * pi)) * (16.0 * th).sin()
        + (2584.0 / (1386693.0 * pi)) * (18.0 * th).sin()
        + (646.0 / (1050525.0 * pi)) * (20.0 * th).sin()
        + (2584.0 / (14329161.0 * pi)) * (22.0 * th).sin()
        + (323.0 / (6947472.0 * pi)) * (24.0 * th).sin()
        + (646.0 / (62093031.0 * pi)) * (26.0 * th).sin()
        + (19.0 / (9552774.0 * pi)) * (28.0 * th).sin()
        + (38.0 / (119409675.0 * pi)) * (30.0 * th).sin()
        + (19.0 / (458533152.0 * pi)) * (32.0 * th).sin()
        + (38.0 / (9013042269.0 * pi)) * (34.0 * th).sin()
        + (1.0 / (3181073742.0 * pi)) * (36.0 * th).sin()
        + (2.0 / (130954202379.0 * pi)) * (38.0 * th).sin()
        + (1.0 / (2756930576400.0 * pi)) * (40.0 * th).sin())
        .clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_c40(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_cos40(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_c40(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos40_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_cos40(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_c40(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos40_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_cos40(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_c40(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos40_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_cos40(y, loc, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_c40(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = cos40_cdf(kk, loc, scale);
    let hi = cos40_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}
/// Unit cosine-fortieth HMM ($f\propto\cos^{40}(\pi u/2)$ on the odds $y/(1-y)$, $|u|<1$).
///
/// Half-width is free and expanded to cover every odds value; location $\mu$ sits below the sample and is not identification `p`. Distinct from [`UnitCosine39Hmm`] ($\cos^{39}$) and [`UnitCosine38Hmm`] ($\cos^{38}$).
#[derive(Clone, Debug)]
pub struct UnitCosine40Hmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for UnitCosine40Hmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl UnitCosine40Hmm {
    /// `k`-state UnitCosine40Hmm.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitCosine40Hmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted UnitCosine40Hmm.
#[derive(Clone, Debug)]
pub struct FittedUnitCosine40Hmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Free half-width expanded to cover every observation.
    pub scale: Vector,
    /// Pinned locations below the sample (not identification `p`).
    pub loc: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedUnitCosine40Hmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_unit_c40(y, self.loc[j], self.scale[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedUnitCosine40Hmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for UnitCosine40Hmm {
    type Fitted = FittedUnitCosine40Hmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitCosine40Hmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let loc = Vector::from_iter((0..k).map(|j| -0.20 - 0.05 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            let y = x.get(i, 0);
            if y.is_finite() && (y <= 0.0 || y >= 1.0) {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "UnitCosine40Hmm skipped {n_skip} observations outside (0,1)"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedUnitCosine40Hmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                scale: Vector::filled(k, 5.00),
                loc,
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..k).map(|j| 5.00 + 0.40 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedUnitCosine40Hmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut mx = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 || y >= 1.0 {
                        continue;
                    }
                    let z = y / (1.0 - y);
                    if !z.is_finite() || z <= 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    mx = mx.max((z - loc[j]).abs());
                }
                if wsum > 1e-12 {
                    scale[j] = (mx * 1.40 + 2.50).clamp(0.80, 40.00);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedUnitCosine40Hmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedUnitCosine40Hmm {
            labels,
            start,
            trans,
            scale,
            loc,
            loglik,
        })
    }
}

