fn log_cos50(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = (y - loc) / scale;
    if u.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let c = (std::f64::consts::PI * u / 2.0).cos();
    if c <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let c2 = c * c;
    let c4 = c2 * c2;
    let dens = (70368744177664.0 / (15801325804719.0 * scale))
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c2;
    dens.max(1e-15).ln()
}

fn cos50_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    let th = std::f64::consts::PI * u / 2.0;
    let pi = std::f64::consts::PI;
    (0.5
        + th / pi
        + (25.0 / (26.0 * pi)) * (2.0 * th).sin()
        + (50.0 / (117.0 * pi)) * (4.0 * th).sin()
        + (575.0 / (2457.0 * pi)) * (6.0 * th).sin()
        + (6325.0 / (47502.0 * pi)) * (8.0 * th).sin()
        + (253.0 / (3393.0 * pi)) * (10.0 * th).sin()
        + (12650.0 / (315549.0 * pi)) * (12.0 * th).sin()
        + (120175.0 / (5890248.0 * pi)) * (14.0 * th).sin()
        + (10925.0 / (1121952.0 * pi)) * (16.0 * th).sin()
        + (10925.0 / (2524392.0 * pi)) * (18.0 * th).sin()
        + (437.0 / (245427.0 * pi)) * (20.0 * th).sin()
        + (10925.0 / (16198182.0 * pi)) * (22.0 * th).sin()
        + (10925.0 / (46701252.0 * pi)) * (24.0 * th).sin()
        + (575.0 / (7783542.0 * pi)) * (26.0 * th).sin()
        + (575.0 / (27242397.0 * pi)) * (28.0 * th).sin()
        + (253.0 / (46701252.0 * pi)) * (30.0 * th).sin()
        + (6325.0 / (5106003552.0 * pi)) * (32.0 * th).sin()
        + (6325.0 / (25317267612.0 * pi)) * (34.0 * th).sin()
        + (6325.0 / (144085037733.0 * pi)) * (36.0 * th).sin()
        + (575.0 / (86908435458.0 * pi)) * (38.0 * th).sin()
        + (23.0 / (27444769092.0 * pi)) * (40.0 * th).sin()
        + (25.0 / (288170075466.0 * pi)) * (42.0 * th).sin()
        + (25.0 / (3547236405141.0 * pi)) * (44.0 * th).sin()
        + (25.0 / (59335590776904.0 * pi)) * (46.0 * th).sin()
        + (25.0 / (1516927277253024.0 * pi)) * (48.0 * th).sin()
        + (1.0 / (3160265160943800.0 * pi)) * (50.0 * th).sin())
        .clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_c50(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_cos50(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_c50(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos50_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_cos50(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_c50(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos50_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_cos50(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_c50(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos50_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_cos50(y, loc, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_c50(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = cos50_cdf(kk, loc, scale);
    let hi = cos50_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}
/// Unit cosine-fiftieth HMM ($f\propto\cos^{50}(\pi u/2)$ on the odds $y/(1-y)$, $|u|<1$).
