fn log_cos51(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = (y - loc) / scale;
    if u.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let c = (std::f64::consts::PI * u / 2.0).cos();
    if c <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let c2 = c * c;
    let c4 = c2 * c2;
    let dens = (805867616040669.0 * std::f64::consts::PI / (562949953421312.0 * scale))
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c2
        * c;
    dens.max(1e-15).ln()
}

fn cos51_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    let s = (std::f64::consts::PI * u / 2.0).sin();
        let s2 = s * s;
        let s3 = s * s2;
        let s5 = s3 * s2;
        let s7 = s5 * s2;
        let s9 = s7 * s2;
        let s11 = s9 * s2;
        let s13 = s11 * s2;
        let s15 = s13 * s2;
        let s17 = s15 * s2;
        let s19 = s17 * s2;
        let s21 = s19 * s2;
        let s23 = s21 * s2;
        let s25 = s23 * s2;
        let s27 = s25 * s2;
        let s29 = s27 * s2;
        let s31 = s29 * s2;
        let s33 = s31 * s2;
        let s35 = s33 * s2;
        let s37 = s35 * s2;
        let s39 = s37 * s2;
        let s41 = s39 * s2;
        let s43 = s41 * s2;
        let s45 = s43 * s2;
        let s47 = s45 * s2;
        let s49 = s47 * s2;
        let s51 = s49 * s2;
    (0.5 + (805867616040669.0 / 281474976710656.0) * s
        - (6715563467005575.0 / 281474976710656.0) * s3
        + (12088014240610035.0 / 70368744177664.0) * s5
        - (66196268460483525.0 / 70368744177664.0) * s7
        + (566345852384136825.0 / 140737488355328.0) * s9
        - (1946170292738215635.0 / 140737488355328.0) * s11
        + (2744599130784663075.0 / 70368744177664.0) * s13
        - (6456342717179159805.0 / 70368744177664.0) * s15
        + (51270956871716857275.0 / 281474976710656.0) * s17
        - (86650915414772934225.0 / 281474976710656.0) * s19
        + (15679689456006530955.0 / 35184372088832.0) * s21
        - (19522142998585206525.0 / 35184372088832.0) * s23
        + (41907533636962910007.0 / 70368744177664.0) * s25
        - (38803271886076768525.0 / 70368744177664.0) * s27
        + (15483078929912405175.0 / 35184372088832.0) * s29
        - (10621725115359262905.0 / 35184372088832.0) * s31
        + (49889920996384416675.0 / 281474976710656.0) * s33
        - (24903036194833902105.0 / 281474976710656.0) * s35
        + (2617436236694253975.0 / 70368744177664.0) * s37
        - (914866376928221025.0 / 70368744177664.0) * s39
        + (522143249271228585.0 / 140737488355328.0) * s41
        - (118537503987377475.0 / 140737488355328.0) * s43
        + (10297197316075215.0 / 70368744177664.0) * s45
        - (1285958961767025.0 / 70368744177664.0) * s47
        + (411156946959525.0 / 281474976710656.0) * s49
        - (15801325804719.0 / 281474976710656.0) * s51)
        .clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_c51(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_cos51(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_c51(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos51_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_cos51(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_c51(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos51_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_cos51(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_c51(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos51_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_cos51(y, loc, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_c51(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = cos51_cdf(kk, loc, scale);
    let hi = cos51_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}
