fn log_cos70(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = (y - loc) / scale;
    if u.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let c = (std::f64::consts::PI * u / 2.0).cos();
    if c <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let c2 = c * c;
    let c4 = c2 * c2;
    let dens = (73786976294838206464.0 / (14023284727082855679.0 * scale))
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c2;
    dens.max(1e-15).ln()
}

fn cos70_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    let th = std::f64::consts::PI * u / 2.0;
    let pi = std::f64::consts::PI;
    (0.5
        + th / pi
        + (35.0 / (36.0 * pi)) * (2.0 * th).sin()
        + (595.0 / (1332.0 * pi)) * (4.0 * th).sin()
        + (6545.0 / (25308.0 * pi)) * (6.0 * th).sin()
        + (13090.0 / (82251.0 * pi)) * (8.0 * th).sin()
        + (40579.0 / (411255.0 * pi)) * (10.0 * th).sin()
        + (202895.0 / (3372291.0 * pi)) * (12.0 * th).sin()
        + (840565.0 / (23606037.0 * pi)) * (14.0 * th).sin()
        + (5883955.0 / (290017026.0 * pi)) * (16.0 * th).sin()
        + (534905.0 / (48336171.0 * pi)) * (18.0 * th).sin()
        + (106981.0 / (18590835.0 * pi)) * (20.0 * th).sin()
        + (2674525.0 / (940696251.0 * pi)) * (22.0 * th).sin()
        + (5349050.0 / (4019338527.0 * pi)) * (24.0 * th).sin()
        + (2674525.0 / (4543600074.0 * pi)) * (26.0 * th).sin()
        + (4202825.0 / (17125877202.0 * pi)) * (28.0 * th).sin()
        + (168113.0 / (1747538490.0 * pi)) * (30.0 * th).sin()
        + (49445.0 / (1398030792.0 * pi)) * (32.0 * th).sin()
        + (49445.0 / (4065326382.0 * pi)) * (34.0 * th).sin()
        + (49445.0 / (12674252838.0 * pi)) * (36.0 * th).sin()
        + (840565.0 / (722432411766.0 * pi)) * (38.0 * th).sin()
        + (30566.0 / (95056896285.0 * pi)) * (40.0 * th).sin()
        + (76415.0 / (931557583593.0 * pi)) * (42.0 * th).sin()
        + (76415.0 / (3973378264713.0 * pi)) * (44.0 * th).sin()
        + (2635.0 / (639074825793.0 * pi)) * (46.0 * th).sin()
        + (2635.0 / (3278731714938.0 * pi)) * (48.0 * th).sin()
        + (5797.0 / (40984146436725.0 * pi)) * (50.0 * th).sin()
        + (28985.0 / (1300017124972917.0 * pi)) * (52.0 * th).sin()
        + (935.0 / (300003951916827.0 * pi)) * (54.0 * th).sin()
        + (1870.0 / (4900064547974841.0 * pi)) * (56.0 * th).sin()
        + (935.0 / (23200305614901288.0 * pi)) * (58.0 * th).sin()
        + (187.0 / (52000684998916680.0 * pi)) * (60.0 * th).sin()
        + (85.0 / (322404246993283416.0 * pi)) * (62.0 * th).sin()
        + (85.0 / (5574473431883868096.0 * pi)) * (64.0 * th).sin()
        + (5.0 / (7664900968840318632.0 * pi)) * (66.0 * th).sin()
        + (5.0 / (272452388983324053192.0 * pi)) * (68.0 * th).sin()
        + (1.0 / (3926519723583199590120.0 * pi)) * (70.0 * th).sin())
        .clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_c70(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_cos70(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_c70(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos70_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_cos70(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_c70(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos70_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_cos70(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_c70(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos70_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_cos70(y, loc, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_c70(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = cos70_cdf(kk, loc, scale);
    let hi = cos70_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}
