fn log_cos74(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = (y - loc) / scale;
    if u.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let c = (std::f64::consts::PI * u / 2.0).cos();
    if c <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let c2 = c * c;
    let c4 = c2 * c2;
    let dens = (1180591620717411303424.0 / (218266320541953276229.0 * scale))
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c2;
    dens.max(1e-15).ln()
}

fn cos74_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    let th = std::f64::consts::PI * u / 2.0;
    let pi = std::f64::consts::PI;
    (0.5
        + th / pi
        + (37.0 / (38.0 * pi)) * (2.0 * th).sin()
        + (111.0 / (247.0 * pi)) * (4.0 * th).sin()
        + (259.0 / (988.0 * pi)) * (6.0 * th).sin()
        + (13209.0 / (81016.0 * pi)) * (8.0 * th).sin()
        + (20757.0 / (202540.0 * pi)) * (10.0 * th).sin()
        + (27676.0 / (435461.0 * pi)) * (12.0 * th).sin()
        + (116994.0 / (3048227.0 * pi)) * (14.0 * th).sin()
        + (19499.0 / (870922.0 * pi)) * (16.0 * th).sin()
        + (1130942.0 / (90140427.0 * pi)) * (18.0 * th).sin()
        + (15833188.0 / (2353666705.0 * pi)) * (20.0 * th).sin()
        + (35624673.0 / (10356133502.0 * pi)) * (22.0 * th).sin()
        + (1696413.0 / (1013887196.0 * pi)) * (24.0 * th).sin()
        + (5089239.0 / (6590266774.0 * pi)) * (26.0 * th).sin()
        + (598734.0 / (1774302593.0 * pi)) * (28.0 * th).sin()
        + (99789.0 / (716333345.0 * pi)) * (30.0 * th).sin()
        + (3293037.0 / (60745067656.0 * pi)) * (32.0 * th).sin()
        + (365893.0 / (18440466967.0 * pi)) * (34.0 * th).sin()
        + (66526.0 / (9762600159.0 * pi)) * (36.0 * th).sin()
        + (33263.0 / (15186266914.0 * pi)) * (38.0 * th).sin()
        + (99789.0 / (151862669140.0 * pi)) * (40.0 * th).sin()
        + (19499.0 / (106303868398.0 * pi)) * (42.0 * th).sin()
        + (233988.0 / (4927943613593.0 * pi)) * (44.0 * th).sin()
        + (116994.0 / (10303882101149.0 * pi)) * (46.0 * th).sin()
        + (19499.0 / (7807910660498.0 * pi)) * (48.0 * th).sin()
        + (3774.0 / (7507606404325.0 * pi)) * (50.0 * th).sin()
        + (2516.0 / (27327687311743.0 * pi)) * (52.0 * th).sin()
        + (6919.0 / (454060035333576.0 * pi)) * (54.0 * th).sin()
        + (6919.0 / (3060700978915216.0 * pi)) * (56.0 * th).sin()
        + (1887.0 / (6340023456324376.0 * pi)) * (58.0 * th).sin()
        + (629.0 / (18309550498867810.0 * pi)) * (60.0 * th).sin()
        + (111.0 / (32434060883708692.0 * pi)) * (62.0 * th).sin()
        + (111.0 / (385023690490477376.0 * pi)) * (64.0 * th).sin()
        + (37.0 / (1852926510485422372.0 * pi)) * (66.0 * th).sin()
        + (111.0 / (101658286279813854682.0 * pi)) * (68.0 * th).sin()
        + (37.0 / (837185887010231744440.0 * pi)) * (70.0 * th).sin()
        + (37.0 / (31430350158041271776976.0 * pi)) * (72.0 * th).sin()
        + (1.0 / (64606830880418169763784.0 * pi)) * (74.0 * th).sin())
        .clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_c74(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_cos74(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_c74(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos74_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_cos74(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_c74(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos74_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_cos74(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_c74(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos74_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_cos74(y, loc, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_c74(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = cos74_cdf(kk, loc, scale);
    let hi = cos74_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}
/// Unit cosine-seventy-fourth HMM ($f\propto\cos^{74}(\pi u/2)$ on the odds $y/(1-y)$, $|u|<1$).
///
/// Half-width is free and expanded to cover every odds value; location $\mu$ sits below the sample and is not identification `p`. Distinct from [`UnitCosine73Hmm`] ($\cos^{73}$) and [`UnitCosine72Hmm`] ($\cos^{72}$).
#[derive(Clone, Debug)]
pub struct UnitCosine74Hmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for UnitCosine74Hmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl UnitCosine74Hmm {
    /// `k`-state UnitCosine74Hmm.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitCosine74Hmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted UnitCosine74Hmm.
#[derive(Clone, Debug)]
pub struct FittedUnitCosine74Hmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Free half-width expanded to cover every observation.
    pub scale: Vector,
    /// Pinned locations below the sample (not identification `p`).
    pub loc: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedUnitCosine74Hmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_unit_c74(y, self.loc[j], self.scale[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedUnitCosine74Hmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for UnitCosine74Hmm {
    type Fitted = FittedUnitCosine74Hmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitCosine74Hmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let loc = Vector::from_iter((0..k).map(|j| -0.20 - 0.05 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            let y = x.get(i, 0);
            if y.is_finite() && (y <= 0.0 || y >= 1.0) {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "UnitCosine74Hmm skipped {n_skip} observations outside (0,1)"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedUnitCosine74Hmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                scale: Vector::filled(k, 5.00),
                loc,
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..k).map(|j| 5.00 + 0.40 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedUnitCosine74Hmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut mx = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 || y >= 1.0 {
                        continue;
                    }
                    let z = y / (1.0 - y);
                    if !z.is_finite() || z <= 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    mx = mx.max((z - loc[j]).abs());
                }
                if wsum > 1e-12 {
                    scale[j] = (mx * 1.40 + 2.50).clamp(0.80, 40.00);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedUnitCosine74Hmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedUnitCosine74Hmm {
            labels,
            start,
            trans,
            scale,
            loc,
            loglik,
        })
    }
}

