fn log_cos81(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = (y - loc) / scale;
    if u.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let c = (std::f64::consts::PI * u / 2.0).cos();
    if c <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let c2 = c * c;
    let c4 = c2 * c2;
    let dens = (2177020976850057573347805.0 * std::f64::consts::PI / (1208925819614629174706176.0 * scale))
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c;
    dens.max(1e-15).ln()
}

fn cos81_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    let s = (std::f64::consts::PI * u / 2.0).sin();
        let s2 = s * s;
        let s3 = s * s2;
        let s5 = s3 * s2;
        let s7 = s5 * s2;
        let s9 = s7 * s2;
        let s11 = s9 * s2;
        let s13 = s11 * s2;
        let s15 = s13 * s2;
        let s17 = s15 * s2;
        let s19 = s17 * s2;
        let s21 = s19 * s2;
        let s23 = s21 * s2;
        let s25 = s23 * s2;
        let s27 = s25 * s2;
        let s29 = s27 * s2;
        let s31 = s29 * s2;
        let s33 = s31 * s2;
        let s35 = s33 * s2;
        let s37 = s35 * s2;
        let s39 = s37 * s2;
        let s41 = s39 * s2;
        let s43 = s41 * s2;
        let s45 = s43 * s2;
        let s47 = s45 * s2;
        let s49 = s47 * s2;
        let s51 = s49 * s2;
        let s53 = s51 * s2;
        let s55 = s53 * s2;
        let s57 = s55 * s2;
        let s59 = s57 * s2;
        let s61 = s59 * s2;
        let s63 = s61 * s2;
        let s65 = s63 * s2;
        let s67 = s65 * s2;
        let s69 = s67 * s2;
        let s71 = s69 * s2;
        let s73 = s71 * s2;
        let s75 = s73 * s2;
        let s77 = s75 * s2;
        let s79 = s77 * s2;
        let s81 = s79 * s2;
    (0.5 + (2177020976850057573347805.0 / 604462909807314587353088.0) * s
        - (3628368294750095955579675.0 / 75557863725914323419136.0) * s3
        + (84903818097152245360564395.0 / 151115727451828646838272.0) * s5
        - (384088700915688729012077025.0 / 75557863725914323419136.0) * s7
        + (11053219281907042312680883275.0 / 302231454903657293676544.0) * s9
        - (16278377487899462315039119005.0 / 75557863725914323419136.0) * s11
        + (160696803406186999776668226075.0 / 151115727451828646838272.0) * s13
        - (338228510026355494768035028215.0 / 75557863725914323419136.0) * s15
        + (9848418380179174700598666998025.0 / 604462909807314587353088.0) * s17
        - (979082529023660642749575081675.0 / 18889465931478580854784.0) * s19
        + (5492186758047010653138092601015.0 / 37778931862957161709568.0) * s21
        - (6838098137489361089875490787825.0 / 18889465931478580854784.0) * s23
        + (60813486102738717959292698073057.0 / 75557863725914323419136.0) * s25
        - (30320114153787110093664450606225.0 / 18889465931478580854784.0) * s27
        + (108883562650792134277248199467675.0 / 37778931862957161709568.0) * s29
        - (88277641116878784134457142364115.0 / 18889465931478580854784.0) * s31
        + (2073187026229729021339523797945125.0 / 302231454903657293676544.0) * s33
        - (344950446381080963214475388229525.0 / 37778931862957161709568.0) * s35
        + (833889217227538064227185247822125.0 / 75557863725914323419136.0) * s37
        - (458020123362493916518845338547375.0 / 37778931862957161709568.0) * s39
        + (1829846248945768378677728450099025.0 / 151115727451828646838272.0) * s41
        - (415413600259006110331045772170875.0 / 37778931862957161709568.0) * s43
        + (685642245275975741697907870431525.0 / 75557863725914323419136.0) * s45
        - (256877991985911355585247629532625.0 / 37778931862957161709568.0) * s47
        + (1396227997256756279677638476167125.0 / 302231454903657293676544.0) * s49
        - (53658958325945927611140615946815.0 / 18889465931478580854784.0) * s51
        + (59577798431565507434720712916275.0 / 37778931862957161709568.0) * s53
        - (14884419675495490409617093933965.0 / 18889465931478580854784.0) * s55
        + (26672581624008209631268727225025.0 / 75557863725914323419136.0) * s57
        - (2665699273936530594358242171525.0 / 18889465931478580854784.0) * s59
        + (1890752818344052847801638436415.0 / 37778931862957161709568.0) * s61
        - (295278857959516701781617881775.0 / 18889465931478580854784.0) * s63
        + (2575740191739168767848882137945.0 / 604462909807314587353088.0) * s65
        - (75722800752169140619709334675.0 / 75557863725914323419136.0) * s67
        + (30276209337397550682560680275.0 / 151115727451828646838272.0) * s69
        - (2522002146012592753034229705.0 / 75557863725914323419136.0) * s71
        + (1362725664892649052248328075.0 / 302231454903657293676544.0) * s73
        - (35848278752130948041127189.0 / 75557863725914323419136.0) * s75
        + (5513234941373522426010675.0 / 151115727451828646838272.0) * s77
        - (137786137775320099578975.0 / 75557863725914323419136.0) * s79
        + (26876802183334044115405.0 / 604462909807314587353088.0) * s81)
        .clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_c81(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_cos81(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_c81(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos81_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_cos81(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_c81(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos81_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_cos81(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_c81(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos81_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_cos81(y, loc, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_c81(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = cos81_cdf(kk, loc, scale);
    let hi = cos81_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}
/// Unit cosine-eighty-first HMM ($f\propto\cos^{81}(\pi u/2)$ on the odds $y/(1-y)$, $|u|<1$).
///
/// Half-width is free and expanded to cover every odds value; location $\mu$ sits below the sample and is not identification `p`. Distinct from [`UnitCosine80Hmm`] ($\cos^{80}$) and [`UnitCosine79Hmm`] ($\cos^{79}$).
#[derive(Clone, Debug)]
pub struct UnitCosine81Hmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for UnitCosine81Hmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl UnitCosine81Hmm {
    /// `k`-state UnitCosine81Hmm.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitCosine81Hmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted UnitCosine81Hmm.
#[derive(Clone, Debug)]
pub struct FittedUnitCosine81Hmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Free half-width expanded to cover every observation.
    pub scale: Vector,
    /// Pinned locations below the sample (not identification `p`).
    pub loc: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedUnitCosine81Hmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_unit_c81(y, self.loc[j], self.scale[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedUnitCosine81Hmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for UnitCosine81Hmm {
    type Fitted = FittedUnitCosine81Hmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitCosine81Hmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let loc = Vector::from_iter((0..k).map(|j| -0.20 - 0.05 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            let y = x.get(i, 0);
            if y.is_finite() && (y <= 0.0 || y >= 1.0) {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "UnitCosine81Hmm skipped {n_skip} observations outside (0,1)"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedUnitCosine81Hmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                scale: Vector::filled(k, 5.00),
                loc,
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..k).map(|j| 5.00 + 0.40 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedUnitCosine81Hmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut mx = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 || y >= 1.0 {
                        continue;
                    }
                    let z = y / (1.0 - y);
                    if !z.is_finite() || z <= 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    mx = mx.max((z - loc[j]).abs());
                }
                if wsum > 1e-12 {
                    scale[j] = (mx * 1.40 + 2.50).clamp(0.80, 40.00);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedUnitCosine81Hmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedUnitCosine81Hmm {
            labels,
            start,
            trans,
            scale,
            loc,
            loglik,
        })
    }
}

