fn log_tsp91(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = (y - loc) / scale;
    if u.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let dens = (45.5 / scale) * (1.0 - u.abs()).powi(90);
    dens.max(1e-15).ln()
}

fn tsp91_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    if u < 0.0 {
        (0.5 * (1.0 + u).powi(91)).clamp(0.0, 1.0 - 1e-15)
    } else {
        (1.0 - 0.5 * (1.0 - u).powi(91)).clamp(0.0, 1.0 - 1e-15)
    }
}

fn log_unit_s91(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_tsp91(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_s91(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = tsp91_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_tsp91(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_s91(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = tsp91_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_tsp91(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_s91(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = tsp91_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_tsp91(y, loc, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_s91(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = tsp91_cdf(kk, loc, scale);
    let hi = tsp91_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

/// Unit two-sided-power HMM (shape $n=91$, $f\propto(1-|u|)^90$ on the odds $y/(1-y)$).
