        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_kuma_c97(y, self.loc[j], self.scale[j], self.a[j], self.b[j]);
            }
        }
