    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    let s = (std::f64::consts::PI * u / 2.0).sin();
        let s2 = s * s;
        let s3 = s * s2;
        let s5 = s3 * s2;
        let s7 = s5 * s2;
        let s9 = s7 * s2;
        let s11 = s9 * s2;
        let s13 = s11 * s2;
        let s15 = s13 * s2;
