fn log_cos102(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = (y - loc) / scale;
    if u.abs() >= 1.0 {
        return f64::NEG_INFINITY;
    }
    let c = (std::f64::consts::PI * u / 2.0).cos();
    if c <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let c2 = c * c;
    let c4 = c2 * c2;
    let dens = (158456325028528675187087900672.0 / (24975553429171528252000152507.0 * scale))
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c4
        * c2;
    dens.max(1e-15).ln()
}

fn cos102_cdf(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || !loc.is_finite() || scale <= 0.0 {
        return 0.0;
    }
    let u = (y - loc) / scale;
    if u <= -1.0 {
        return 0.0;
    }
    if u >= 1.0 {
        return 1.0 - 1e-15;
    }
    let th = std::f64::consts::PI * u / 2.0;
    let pi = std::f64::consts::PI;
    (0.5
        + th / pi
        + (51.0 / (52.0 * pi)) * (2.0 * th).sin()
        + (1275.0 / (2756.0 * pi)) * (4.0 * th).sin()
        + (20825.0 / (74412.0 * pi)) * (6.0 * th).sin()
        + (4165.0 / (22737.0 * pi)) * (8.0 * th).sin()
        + (5593.0 / (45474.0 * pi)) * (10.0 * th).sin()
        + (643195.0 / (7776054.0 * pi)) * (12.0 * th).sin()
        + (459425.0 / (8352058.0 * pi)) * (14.0 * th).sin()
        + (3215975.0 / (89594804.0 * pi)) * (16.0 * th).sin()
        + (27657385.0 / (1209529854.0 * pi)) * (18.0 * th).sin()
        + (38720339.0 / (2732641522.0 * pi)) * (20.0 * th).sin()
        + (7937669495.0 / (931830759002.0 * pi)) * (22.0 * th).sin()
        + (5669763925.0 / (1143610476957.0 * pi)) * (24.0 * th).sin()
        + (5669763925.0 / (2033085292368.0 * pi)) * (26.0 * th).sin()
        + (161993255.0 / (107004489072.0 * pi)) * (28.0 * th).sin()
        + (8391250609.0 / (10593444418128.0 * pi)) * (30.0 * th).sin()
        + (41956253045.0 / (105149744594752.0 * pi)) * (32.0 * th).sin()
        + (86380520975.0 / (446886414527696.0 * pi)) * (34.0 * th).sin()
        + (63846472025.0 / (709760776014576.0 * pi)) * (36.0 * th).sin()
        + (1824184915.0 / (45405571529552.0 * pi)) * (38.0 * th).sin()
        + (364836983.0 / (21209181438146.0 * pi)) * (40.0 * th).sin()
        + (260597845.0 / (36945025730964.0 * pi)) * (42.0 * th).sin()
        + (9120924575.0 / (3296317295773788.0 * pi)) * (44.0 * th).sin()
        + (246511475.0 / (237665510353596.0 * pi)) * (46.0 * th).sin()
        + (69023213.0 / (185999095059336.0 * pi)) * (48.0 * th).sin()
        + (207069639.0 / (1636103150984900.0 * pi)) * (50.0 * th).sin()
        + (29581377.0 / (719885386433356.0 * pi)) * (52.0 * th).sin()
        + (246511475.0 / (19436905433700612.0 * pi)) * (54.0 * th).sin()
        + (105647775.0 / (28435472764117562.0 * pi)) * (56.0 * th).sin()
        + (3401858355.0 / (3298514840637637192.0 * pi)) * (58.0 * th).sin()
        + (226790557.0 / (837553925052190008.0 * pi)) * (60.0 * th).sin()
        + (193601695.0 / (2884907964068654472.0 * pi)) * (62.0 * th).sin()
        + (968008475.0 / (61792867359406018368.0 * pi)) * (64.0 * th).sin()
        + (138286925.0 / (40246670188034183016.0 * pi)) * (66.0 * th).sin()
        + (1626905.0 / (2303681458574347176.0 * pi)) * (68.0 * th).sin()
        + (18377.0 / (135510674033785128.0 * pi)) * (70.0 * th).sin()
        + (643195.0 / (26526214442113438806.0 * pi)) * (72.0 * th).sin()
        + (3215975.0 / (799716242810382932892.0 * pi)) * (74.0 * th).sin()
        + (22511825.0 / (36549193691685338905956.0 * pi)) * (76.0 * th).sin()
        + (4502365.0 / (51938327877658113182148.0 * pi)) * (78.0 * th).sin()
        + (128639.0 / (11541850639479580707144.0 * pi)) * (80.0 * th).sin()
        + (27965.0 / (21509812555393764045132.0 * pi)) * (82.0 * th).sin()
        + (19975.0 / (146371651291581955331508.0 * pi)) * (84.0 * th).sin()
        + (2975.0 / (233110407612519410342772.0 * pi)) * (86.0 * th).sin()
        + (595.0 / (566512502221122753042318.0 * pi)) * (88.0 * th).sin()
        + (833.0 / (11124245498160228605194608.0 * pi)) * (90.0 * th).sin()
        + (4165.0 / (919192285422054445118117424.0 * pi)) * (92.0 * th).sin()
        + (425.0 / (1878349452818980822632674736.0 * pi)) * (94.0 * th).sin()
        + (425.0 / (47478279786147855686970586944.0 * pi)) * (96.0 * th).sin()
        + (17.0 / (64623214153367914685043298896.0 * pi)) * (98.0 * th).sin()
        + (17.0 / (3330073790556203766933353667600.0 * pi)) * (100.0 * th).sin()
        + (1.0 / (20380051598203967053632124445712.0 * pi)) * (102.0 * th).sin())
        .clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_c102(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let u = y / (1.0 - y);
    if !u.is_finite() || u < 0.0 {
        return f64::NEG_INFINITY;
    }
    log_cos102(u, loc, scale) - 2.0 * (1.0 - y).ln()
}

fn log_beta_c102(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos102_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_cos102(y, loc, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_c102(y: f64, loc: f64, scale: f64, power: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos102_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_cos102(y, loc, scale) + (power - 1.0) * cdf.ln()
}

fn log_kuma_c102(y: f64, loc: f64, scale: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || scale <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = cos102_cdf(y, loc, scale);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln()
        + b.ln()
        + log_cos102(y, loc, scale)
        + (a - 1.0) * cdf.ln()
        + (b - 1.0) * one_m.ln()
}

fn log_disc_c102(y: f64, loc: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = cos102_cdf(kk, loc, scale);
    let hi = cos102_cdf(kk + 1.0, loc, scale);
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}
/// Unit cosine-hundred-and-second HMM ($f\propto\cos^{102}(\pi u/2)$ on the odds $y/(1-y)$, $|u|<1$).
///
/// Half-width is free and expanded to cover every odds value; location $\mu$ sits below the sample and is not identification `p`. Distinct from [`UnitCosine101Hmm`] ($\cos^{101}$) and [`UnitCosine100Hmm`] ($\cos^{100}$).
#[derive(Clone, Debug)]
pub struct UnitCosine102Hmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for UnitCosine102Hmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl UnitCosine102Hmm {
    /// `k`-state UnitCosine102Hmm.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitCosine102Hmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted UnitCosine102Hmm.
#[derive(Clone, Debug)]
pub struct FittedUnitCosine102Hmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Free half-width expanded to cover every observation.
    pub scale: Vector,
    /// Pinned locations below the sample (not identification `p`).
    pub loc: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedUnitCosine102Hmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.scale.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_unit_c102(y, self.loc[j], self.scale[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedUnitCosine102Hmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for UnitCosine102Hmm {
    type Fitted = FittedUnitCosine102Hmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedUnitCosine102Hmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let loc = Vector::from_iter((0..k).map(|j| -0.20 - 0.05 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            let y = x.get(i, 0);
            if y.is_finite() && (y <= 0.0 || y >= 1.0) {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "UnitCosine102Hmm skipped {n_skip} observations outside (0,1)"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedUnitCosine102Hmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                scale: Vector::filled(k, 5.00),
                loc,
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..k).map(|j| 5.00 + 0.40 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedUnitCosine102Hmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut mx = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 || y >= 1.0 {
                        continue;
                    }
                    let z = y / (1.0 - y);
                    if !z.is_finite() || z <= 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    mx = mx.max((z - loc[j]).abs());
                }
                if wsum > 1e-12 {
                    scale[j] = (mx * 1.40 + 2.50).clamp(0.80, 40.00);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedUnitCosine102Hmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                scale: scale.clone(),
                loc: loc.clone(),
                loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedUnitCosine102Hmm {
            labels,
            start,
            trans,
            scale,
            loc,
            loglik,
        })
    }
}

