                let mut wsum = 0.0_f64;
                let mut mx = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y < 1.0 {
                        continue;
                    }
                    let z = y + 1.0;
                    wsum += fb.gamma[t][j];
                    mx = mx.max((z - loc[j]).abs());
                }
